var o=[{title:`Aprender o movimento`,text:`Fique de pé com os joelhos ligeiramente flectidos. Empurre as ancas para trás como se fechasse a porta de um carro com elas e deixe o tronco inclinar-se para a frente enquanto as costas se mantêm numa posição confortável e controlada. Pare quando os isquiotibiais limitarem o movimento ou o tronco já não se mantiver controlado e depois leve as ancas para a frente para se levantar. Está a treinar o movimento da anca, por isso chegar ao chão não é o objetivo.`},{title:`Dobradiça e agachamento`,text:`Ambos os movimentos usam as ancas e os joelhos, com ênfase diferente. Num agachamento os joelhos costumam dobrar mais e o tronco fica mais vertical. Num levantamento terra romeno os joelhos dobram um pouco e as ancas vão mais para trás, o que dá mais trabalho à parte de trás do corpo. Uma ponte de glúteos treina a extensão da anca com o tronco apoiado e é por vezes um ponto de partida mais fácil.`},{title:`Exercícios de ensino`,text:`No toque na parede, fique a um pequeno passo de uma parede e empurre as ancas para trás até lhe tocarem. Uma vara leve colocada ao longo da cabeça, da parte superior das costas e da bacia pode indicar quando a coluna se move muito. Use estes exercícios para aprender e não force uma postura rígida por causa deles.`},{title:`Progressão e erros`,text:`Comece com repetições sem carga e depois passe para um levantamento terra leve com kettlebell ou um levantamento terra romeno com halteres. Mantenha o peso perto e use uma amplitude que consiga controlar. Dobrar demasiado os joelhos transforma o levantamento num agachamento, e perseguir uma profundidade definida pode passar o movimento para as costas. Os swings exigem mais competência do que uma dobradiça lenta.`},{title:`Usar o TrainUp`,text:`O seu plano inclui exercícios de dobradiça adequados ao seu equipamento e objetivo. Se o equilíbrio ou uma zona lombar sensível tornarem difíceis as dobradiças com carga, uma variação com apoio ou uma ponte de anca é uma opção, e pode registar uma limitação nas costas no Perfil. Se a dor persistir, consulte um médico ou fisioterapeuta em vez de montar o seu próprio plano de reabilitação.`}];var s=[{label:`Biblioteca de exercícios da ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`ACE: técnica do swing de kettlebell com as duas mãos`,url:`https://www.acefitness.org/continuing-education/certified/january-2025/8788/the-ace-do-it-better-series-the-two-handed-kettlebell-swing/`},{label:`NSCA: segurança e fundamentos do treino de resistência`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var t={sections:o,sources:s};export{t as default,o as sections,s as sources};